insert into kafaa_smr_deltas (id, role_id, tech_id, rank, path_only, dims, changes_en, changes_ar, stays_en, stays_ar, skills, training, concept_role_ids, sources, benchmark_ids, status, listed, version, as_of, sort, updated_by, updated_at) values
('smrd:outage-manager-planner:tech-htgr', 'outage-manager-planner', 'tech-htgr', 2, false, '[{"dim":"multi_module","change":"new","text_en":"Several smaller reactor modules may share one plant and one control room. Planning moves from a few long outages to shorter, more frequent windows across several units.","text_ar":"قد تتشارك عدة وحدات مفاعل أصغر محطة واحدة وغرفة تحكم واحدة. ينتقل التخطيط من فترات إيقاف قليلة وطويلة إلى نوافذ أقصر وأكثر تكراراً عبر عدة وحدات."},{"dim":"digital_ic","change":"adapts","text_en":"New digital instrumentation for gas coolant and high-temperature systems. Electronic work packages and digital tools tie the schedule to live plant data.","text_ar":"أجهزة رقمية جديدة لأنظمة التبريد بالغاز والأنظمة عالية الحرارة. تربط حزم العمل الإلكترونية والأدوات الرقمية الجدول ببيانات المحطة الحية."},{"dim":"factory_fab","change":"new","text_en":"Reactor modules and major components are planned to be factory-built. Replacing modules instead of repairing in place changes scope, logistics and the critical path.","text_ar":"يُخطَّط لتصنيع وحدات المفاعل والمكونات الرئيسية في المصنع. يغيّر استبدال الوحدات بدلاً من إصلاحها في مكانها نطاق العمل والإمداد والمسار الحرج."},{"dim":"maintenance","change":"adapts","text_en":"Gas coolant and a different fuel form change inspection and maintenance tasks. A different refuelling cycle and design basis reshape the outage schedule template.","text_ar":"يغيّر التبريد بالغاز وشكل الوقود المختلف مهام الفحص والصيانة. تعيد دورة تزويد بالوقود وأساس تصميم مختلفان تشكيل قالب جدول الإيقاف."},{"dim":"systems","change":"adapts","text_en":"Gas coolant, a different fuel form and high-temperature heat that can also serve industrial processes. New equipment types to sequence and isolate safely.","text_ar":"تبريد بالغاز وشكل وقود مختلف وحرارة عالية يمكن أن تخدم العمليات الصناعية أيضاً. أنواع جديدة من المعدات لترتيبها وعزلها بأمان."}]'::jsonb, 'High-temperature gas-cooled: the biggest shifts for this role are multi-module operation and factory fabrication; digital I&C, the maintenance regime and plant systems, coolant and fuel adapt. Planning assumption; no deployment decision implied.', 'المفاعلات عالية الحرارة المبرّدة بالغاز: أكبر التحولات لهذا الدور في التشغيل متعدد الوحدات، والتصنيع في المصنع، بينما يتكيف كل من الأجهزة والتحكم الرقمية، ونظام الصيانة، وأنظمة المحطة والمبرد والوقود. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Risk-informed scheduling, work control discipline and the safety review of every outage plan stay the same.', 'تبقى الجدولة المستنيرة بالمخاطر وانضباط التحكم في الأعمال ومراجعة السلامة لكل خطة إيقاف كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":2},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":2}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-dp-dic-l1"},{"kind":"pathway","ref":"pw-adv-multimodule-l1"},{"kind":"lane","ref":"lane-hydrogen"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"osu-e2-center","label":"Oregon State University · NuScale Energy Exploration (E2) Center","url":"https://engineering.oregonstate.edu/facilities/energy-exploration-e2-center","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 20, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:outage-manager-planner:tech-fast', 'outage-manager-planner', 'tech-fast', 3, false, '[{"dim":"multi_module","change":"adapts","text_en":"Fleet concepts with several units change how operations and support are organised. Planning moves from a few long outages to shorter, more frequent windows across several units.","text_ar":"تغيّر مفاهيم الأساطيل متعددة الوحدات طريقة تنظيم التشغيل والدعم. ينتقل التخطيط من فترات إيقاف قليلة وطويلة إلى نوافذ أقصر وأكثر تكراراً عبر عدة وحدات."},{"dim":"digital_ic","change":"adapts","text_en":"Instrumentation designed for liquid-metal coolant and a fast neutron spectrum. Electronic work packages and digital tools tie the schedule to live plant data.","text_ar":"أجهزة مصممة لمبرد معدني سائل وطيف نيوتروني سريع. تربط حزم العمل الإلكترونية والأدوات الرقمية الجدول ببيانات المحطة الحية."},{"dim":"factory_fab","change":"adapts","text_en":"More factory-built components and modular construction. Replacing modules instead of repairing in place changes scope, logistics and the critical path.","text_ar":"مكونات مصنّعة في المصنع وإنشاء معياري أكثر. يغيّر استبدال الوحدات بدلاً من إصلاحها في مكانها نطاق العمل والإمداد والمسار الحرج."},{"dim":"maintenance","change":"new","text_en":"Liquid-metal coolant changes how components are inspected, drained and handled. A different refuelling cycle and design basis reshape the outage schedule template.","text_ar":"يغيّر المبرد المعدني السائل طريقة فحص المكونات وتصريفها ومناولتها. تعيد دورة تزويد بالوقود وأساس تصميم مختلفان تشكيل قالب جدول الإيقاف."},{"dim":"systems","change":"adapts","text_en":"Liquid-metal coolant handling and chemistry, and fast-spectrum reactor physics. New equipment types to sequence and isolate safely.","text_ar":"مناولة المبرد المعدني السائل وكيمياؤه، وفيزياء المفاعلات ذات الطيف السريع. أنواع جديدة من المعدات لترتيبها وعزلها بأمان."}]'::jsonb, 'Fast reactors with liquid-metal coolant: the biggest shifts for this role are the maintenance regime; multi-module operation, digital I&C, factory fabrication and plant systems, coolant and fuel adapt. Planning assumption; no deployment decision implied.', 'المفاعلات السريعة المبرّدة بالمعادن السائلة: أكبر التحولات لهذا الدور في نظام الصيانة، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية، والتصنيع في المصنع، وأنظمة المحطة والمبرد والوقود. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Risk-informed scheduling, work control discipline and the safety review of every outage plan stay the same.', 'تبقى الجدولة المستنيرة بالمخاطر وانضباط التحكم في الأعمال ومراجعة السلامة لكل خطة إيقاف كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":1},{"skill_id":"sk-fs-dp-robotics","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-dp-dic-l1"},{"kind":"pathway","ref":"pw-adv-multimodule-l1"},{"kind":"pathway","ref":"pw-dp-robotics-l1"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 21, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:maintenance-technician-engineer:tech-bwr', 'maintenance-technician-engineer', 'tech-bwr', 1, false, '[{"dim":"multi_module","change":"adapts","text_en":"A fleet of small units means several smaller reactors to run and maintain rather than a few large ones. The same task repeated across many smaller units rewards standard work and good records.","text_ar":"يعني أسطول من الوحدات الصغيرة تشغيل وصيانة عدد من المفاعلات الأصغر بدلاً من عدد قليل من المفاعلات الكبيرة. تكرار المهمة نفسها في وحدات صغيرة كثيرة يكافئ العمل المعياري والسجلات الجيدة."},{"dim":"passive_safety","change":"new","text_en":"Small reactor designs put more weight on passive cooling that works for a period without AC power or operator action. Passive systems have fewer pumps and diesels to maintain, but valves, heat exchangers and their testing matter more.","text_ar":"تعطي تصاميم المفاعلات الصغيرة وزناً أكبر للتبريد الخامل الذي يعمل لفترة دون كهرباء متناوبة أو تدخل من المشغلين. للأنظمة الخاملة مضخات ومولدات ديزل أقل للصيانة، لكن الصمامات والمبادلات الحرارية واختبارها تصبح أهم."},{"dim":"digital_ic","change":"adapts","text_en":"A different digital control platform and alarm philosophy from the APR-1400 digital I&C you know. A different digital platform to calibrate, test and fault-find.","text_ar":"منصة تحكم رقمية وفلسفة إنذارات تختلفان عن الأجهزة والتحكم الرقمية في APR-1400 التي تعرفها. منصة رقمية مختلفة للمعايرة والاختبار وتحديد الأعطال."},{"dim":"factory_fab","change":"adapts","text_en":"More of the plant arrives as factory-built modules, so quality evidence moves upstream to the factory. More component swaps and vendor support, fewer field repairs; receiving inspection grows.","text_ar":"يصل جزء أكبر من المحطة على شكل وحدات مصنّعة في المصنع، فتنتقل أدلة الجودة إلى المصنع. مزيد من استبدال المكونات ودعم الموردين وإصلاحات ميدانية أقل، ويزداد الفحص عند الاستلام."},{"dim":"maintenance","change":"adapts","text_en":"Maintenance windows and refuelling follow a different design basis and outage rhythm. New maintenance regimes, with remote inspection and robotics where access is harder.","text_ar":"تتبع نوافذ الصيانة والتزويد بالوقود أساس تصميم وإيقاع إيقاف مختلفين. أنظمة صيانة جديدة، مع الفحص عن بعد والروبوتات حيث يصعب الوصول."},{"dim":"systems","change":"new","text_en":"A boiling water reactor makes steam in the reactor itself, so plant systems, water chemistry and radiation zones differ from Barakah''s two-loop APR-1400 units. New coolant and materials mean new tools, procedures and hazards to learn.","text_ar":"يولّد مفاعل الماء المغلي البخار داخل المفاعل نفسه، فتختلف أنظمة المحطة وكيمياء الماء ومناطق الإشعاع عن وحدات APR-1400 ذات الدائرتين في براكة. يعني المبرد والمواد الجديدة أدوات وإجراءات ومخاطر جديدة يجب تعلمها."}]'::jsonb, 'Small boiling water reactor: the biggest shifts for this role are passive safety and plant systems, coolant and fuel; multi-module operation, digital I&C, factory fabrication and the maintenance regime adapt. Planning assumption; no deployment decision implied.', 'مفاعل الماء المغلي الصغير: أكبر التحولات لهذا الدور في السلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية، والتصنيع في المصنع، ونظام الصيانة. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Work package discipline, self-checking, foreign material exclusion and pre-job briefs stay exactly as today.', 'يبقى انضباط حزم العمل والتحقق الذاتي ومنع المواد الغريبة وإحاطات ما قبل العمل كما هي اليوم.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-dp-dic-l1"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"gevh-smr-centre-2025","label":"GE Vernova · GE Vernova Hitachi SMR engineering and service centre, Ontario (June 2025)","url":"https://www.gevernova.com/news/press-releases/ge-vernova-hitachi-nuclear-energy-canada-small-modular-reactor-engineering-service-centre-ontario","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 22, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:maintenance-technician-engineer:tech-fast', 'maintenance-technician-engineer', 'tech-fast', 2, false, '[{"dim":"multi_module","change":"adapts","text_en":"Fleet concepts with several units change how operations and support are organised. The same task repeated across many smaller units rewards standard work and good records.","text_ar":"تغيّر مفاهيم الأساطيل متعددة الوحدات طريقة تنظيم التشغيل والدعم. تكرار المهمة نفسها في وحدات صغيرة كثيرة يكافئ العمل المعياري والسجلات الجيدة."},{"dim":"passive_safety","change":"new","text_en":"Fast-reactor concepts rely on passive heat removal through the coolant''s natural circulation. Passive systems have fewer pumps and diesels to maintain, but valves, heat exchangers and their testing matter more.","text_ar":"تعتمد مفاهيم المفاعلات السريعة على إزالة الحرارة بطريقة خاملة عبر الدوران الطبيعي للمبرد. للأنظمة الخاملة مضخات ومولدات ديزل أقل للصيانة، لكن الصمامات والمبادلات الحرارية واختبارها تصبح أهم."},{"dim":"digital_ic","change":"adapts","text_en":"Instrumentation designed for liquid-metal coolant and a fast neutron spectrum. A different digital platform to calibrate, test and fault-find.","text_ar":"أجهزة مصممة لمبرد معدني سائل وطيف نيوتروني سريع. منصة رقمية مختلفة للمعايرة والاختبار وتحديد الأعطال."},{"dim":"factory_fab","change":"adapts","text_en":"More factory-built components and modular construction. More component swaps and vendor support, fewer field repairs; receiving inspection grows.","text_ar":"مكونات مصنّعة في المصنع وإنشاء معياري أكثر. مزيد من استبدال المكونات ودعم الموردين وإصلاحات ميدانية أقل، ويزداد الفحص عند الاستلام."},{"dim":"maintenance","change":"new","text_en":"Liquid-metal coolant changes how components are inspected, drained and handled. New maintenance regimes, with remote inspection and robotics where access is harder.","text_ar":"يغيّر المبرد المعدني السائل طريقة فحص المكونات وتصريفها ومناولتها. أنظمة صيانة جديدة، مع الفحص عن بعد والروبوتات حيث يصعب الوصول."},{"dim":"systems","change":"new","text_en":"Liquid-metal coolant handling and chemistry, and fast-spectrum reactor physics. New coolant and materials mean new tools, procedures and hazards to learn.","text_ar":"مناولة المبرد المعدني السائل وكيمياؤه، وفيزياء المفاعلات ذات الطيف السريع. يعني المبرد والمواد الجديدة أدوات وإجراءات ومخاطر جديدة يجب تعلمها."}]'::jsonb, 'Fast reactors with liquid-metal coolant: the biggest shifts for this role are passive safety, the maintenance regime and plant systems, coolant and fuel; multi-module operation, digital I&C and factory fabrication adapt. Planning assumption; no deployment decision implied.', 'المفاعلات السريعة المبرّدة بالمعادن السائلة: أكبر التحولات لهذا الدور في السلامة الخاملة، ونظام الصيانة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية، والتصنيع في المصنع. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Work package discipline, self-checking, foreign material exclusion and pre-job briefs stay exactly as today.', 'يبقى انضباط حزم العمل والتحقق الذاتي ومنع المواد الغريبة وإحاطات ما قبل العمل كما هي اليوم.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":1},{"skill_id":"sk-fs-dp-robotics","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-dp-dic-l1"}]'::jsonb, array['fr-liquid-metal']::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 23, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:maintenance-technician-engineer:tech-micro', 'maintenance-technician-engineer', 'tech-micro', 3, false, '[{"dim":"multi_module","change":"adapts","text_en":"Many small transportable units rather than one plant. The same task repeated across many smaller units rewards standard work and good records.","text_ar":"وحدات صغيرة كثيرة قابلة للنقل بدلاً من محطة واحدة. تكرار المهمة نفسها في وحدات صغيرة كثيرة يكافئ العمل المعياري والسجلات الجيدة."},{"dim":"passive_safety","change":"new","text_en":"Microreactor concepts are designed to cool themselves passively for long periods. Passive systems have fewer pumps and diesels to maintain, but valves, heat exchangers and their testing matter more.","text_ar":"صُممت مفاهيم المفاعلات المتناهية الصغر لتبريد نفسها بطريقة خاملة لفترات طويلة. للأنظمة الخاملة مضخات ومولدات ديزل أقل للصيانة، لكن الصمامات والمبادلات الحرارية واختبارها تصبح أهم."},{"dim":"digital_ic","change":"new","text_en":"Remote and autonomous operation concepts: monitoring from a distance rather than from a local control room. A different digital platform to calibrate, test and fault-find.","text_ar":"مفاهيم التشغيل عن بعد والتشغيل الذاتي: المراقبة من بعيد بدلاً من غرفة تحكم محلية. منصة رقمية مختلفة للمعايرة والاختبار وتحديد الأعطال."},{"dim":"factory_fab","change":"new","text_en":"Units are built in a factory and transported as complete units. More component swaps and vendor support, fewer field repairs; receiving inspection grows.","text_ar":"تُبنى الوحدات في المصنع وتُنقل وحدات كاملة. مزيد من استبدال المكونات ودعم الموردين وإصلاحات ميدانية أقل، ويزداد الفحص عند الاستلام."},{"dim":"maintenance","change":"new","text_en":"Maintenance shifts towards remote monitoring and returning units to the factory. New maintenance regimes, with remote inspection and robotics where access is harder.","text_ar":"تنتقل الصيانة نحو المراقبة عن بعد وإعادة الوحدات إلى المصنع. أنظمة صيانة جديدة، مع الفحص عن بعد والروبوتات حيث يصعب الوصول."},{"dim":"systems","change":"adapts","text_en":"Compact designs with their own coolant and fuel choices. New coolant and materials mean new tools, procedures and hazards to learn.","text_ar":"تصاميم مدمجة لها خياراتها الخاصة من المبرد والوقود. يعني المبرد والمواد الجديدة أدوات وإجراءات ومخاطر جديدة يجب تعلمها."}]'::jsonb, 'Microreactors: the biggest shifts for this role are passive safety, digital I&C, factory fabrication and the maintenance regime; multi-module operation and plant systems, coolant and fuel adapt. Planning assumption; no deployment decision implied.', 'المفاعلات المتناهية الصغر: أكبر التحولات لهذا الدور في السلامة الخاملة، والأجهزة والتحكم الرقمية، والتصنيع في المصنع، ونظام الصيانة، بينما يتكيف كل من التشغيل متعدد الوحدات، وأنظمة المحطة والمبرد والوقود. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Work package discipline, self-checking, foreign material exclusion and pre-job briefs stay exactly as today.', 'يبقى انضباط حزم العمل والتحقق الذاتي ومنع المواد الغريبة وإحاطات ما قبل العمل كما هي اليوم.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-dp-dic","level":2},{"skill_id":"sk-fs-adv-factoryqa","level":2},{"skill_id":"sk-fs-dp-robotics","level":1},{"skill_id":"sk-fs-adv-micro","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-adv-micro-l1"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"iaea-ai-bulletin","label":"IAEA Bulletin · Enhancing nuclear power production with artificial intelligence (2025)","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 24, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:maintenance-technician-engineer:tech-msr', 'maintenance-technician-engineer', 'tech-msr', 4, false, '[{"dim":"multi_module","change":"adapts","text_en":"Modular plant concepts with several units. The same task repeated across many smaller units rewards standard work and good records.","text_ar":"مفاهيم محطات معيارية بعدة وحدات. تكرار المهمة نفسها في وحدات صغيرة كثيرة يكافئ العمل المعياري والسجلات الجيدة."},{"dim":"passive_safety","change":"new","text_en":"Molten salt concepts rely on passive features of the salt and the design to remove heat. Passive systems have fewer pumps and diesels to maintain, but valves, heat exchangers and their testing matter more.","text_ar":"تعتمد مفاهيم الأملاح المنصهرة على الخصائص الخاملة للملح والتصميم لإزالة الحرارة. للأنظمة الخاملة مضخات ومولدات ديزل أقل للصيانة، لكن الصمامات والمبادلات الحرارية واختبارها تصبح أهم."},{"dim":"digital_ic","change":"adapts","text_en":"Instrumentation and sampling designed for hot salt systems. A different digital platform to calibrate, test and fault-find.","text_ar":"أجهزة وأخذ عينات مصممة لأنظمة الأملاح الساخنة. منصة رقمية مختلفة للمعايرة والاختبار وتحديد الأعطال."},{"dim":"factory_fab","change":"adapts","text_en":"Factory-built modules for salt systems. More component swaps and vendor support, fewer field repairs; receiving inspection grows.","text_ar":"وحدات مصنّعة في المصنع لأنظمة الأملاح. مزيد من استبدال المكونات ودعم الموردين وإصلاحات ميدانية أقل، ويزداد الفحص عند الاستلام."},{"dim":"maintenance","change":"new","text_en":"Salt-wetted components bring new handling and inspection tasks. New maintenance regimes, with remote inspection and robotics where access is harder.","text_ar":"تجلب المكونات الملامسة للملح مهام مناولة وفحص جديدة. أنظمة صيانة جديدة، مع الفحص عن بعد والروبوتات حيث يصعب الوصول."},{"dim":"systems","change":"new","text_en":"Salt chemistry and materials replace water chemistry. New coolant and materials mean new tools, procedures and hazards to learn.","text_ar":"تحل كيمياء الأملاح وموادها محل كيمياء الماء. يعني المبرد والمواد الجديدة أدوات وإجراءات ومخاطر جديدة يجب تعلمها."}]'::jsonb, 'Molten salt: the biggest shifts for this role are passive safety, the maintenance regime and plant systems, coolant and fuel; multi-module operation, digital I&C and factory fabrication adapt. Planning assumption; no deployment decision implied.', 'مفاعلات الأملاح المنصهرة: أكبر التحولات لهذا الدور في السلامة الخاملة، ونظام الصيانة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية، والتصنيع في المصنع. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Work package discipline, self-checking, foreign material exclusion and pre-job briefs stay exactly as today.', 'يبقى انضباط حزم العمل والتحقق الذاتي ومنع المواد الغريبة وإحاطات ما قبل العمل كما هي اليوم.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":1},{"skill_id":"sk-fs-dp-robotics","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-dp-dic-l1"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 25, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:systems-design-plant-engineer:tech-bwr', 'systems-design-plant-engineer', 'tech-bwr', 1, false, '[{"dim":"multi_module","change":"adapts","text_en":"A fleet of small units means several smaller reactors to run and maintain rather than a few large ones. Design and configuration control span several identical units, so a change is assessed once and applied many times.","text_ar":"يعني أسطول من الوحدات الصغيرة تشغيل وصيانة عدد من المفاعلات الأصغر بدلاً من عدد قليل من المفاعلات الكبيرة. يمتد التصميم والتحكم في التهيئة إلى عدة وحدات متطابقة، فيُقيَّم التغيير مرة ويُطبَّق مرات."},{"dim":"passive_safety","change":"new","text_en":"Small reactor designs put more weight on passive cooling that works for a period without AC power or operator action. Safety analysis leans on natural circulation and passive heat removal rather than pumped systems.","text_ar":"تعطي تصاميم المفاعلات الصغيرة وزناً أكبر للتبريد الخامل الذي يعمل لفترة دون كهرباء متناوبة أو تدخل من المشغلين. يعتمد تحليل السلامة على الدوران الطبيعي وإزالة الحرارة الخاملة بدلاً من الأنظمة المعتمدة على المضخات."},{"dim":"digital_ic","change":"adapts","text_en":"A different digital control platform and alarm philosophy from the APR-1400 digital I&C you know. A new digital architecture to understand, modify and keep under configuration control.","text_ar":"منصة تحكم رقمية وفلسفة إنذارات تختلفان عن الأجهزة والتحكم الرقمية في APR-1400 التي تعرفها. بنية رقمية جديدة يجب فهمها وتعديلها وإبقاؤها تحت التحكم في التهيئة."},{"dim":"factory_fab","change":"adapts","text_en":"More of the plant arrives as factory-built modules, so quality evidence moves upstream to the factory. The design authority works closer to the factory: design changes, deviations and acceptance move upstream.","text_ar":"يصل جزء أكبر من المحطة على شكل وحدات مصنّعة في المصنع، فتنتقل أدلة الجودة إلى المصنع. تعمل جهة التصميم أقرب إلى المصنع، فتنتقل تغييرات التصميم والانحرافات والقبول إلى مراحل أبكر."},{"dim":"maintenance","change":"adapts","text_en":"Maintenance windows and refuelling follow a different design basis and outage rhythm. System health monitoring starts from new failure modes and new performance data.","text_ar":"تتبع نوافذ الصيانة والتزويد بالوقود أساس تصميم وإيقاع إيقاف مختلفين. تبدأ مراقبة سلامة الأنظمة من أنماط أعطال جديدة وبيانات أداء جديدة."},{"dim":"systems","change":"new","text_en":"A boiling water reactor makes steam in the reactor itself, so plant systems, water chemistry and radiation zones differ from Barakah''s two-loop APR-1400 units. Core physics, coolant behaviour and materials differ, so analysis methods and codes change.","text_ar":"يولّد مفاعل الماء المغلي البخار داخل المفاعل نفسه، فتختلف أنظمة المحطة وكيمياء الماء ومناطق الإشعاع عن وحدات APR-1400 ذات الدائرتين في براكة. تختلف فيزياء القلب وسلوك المبرد والمواد، فتتغير طرق التحليل وبرمجياته."}]'::jsonb, 'Small boiling water reactor: the biggest shifts for this role are passive safety and plant systems, coolant and fuel; multi-module operation, digital I&C, factory fabrication and the maintenance regime adapt. Planning assumption; no deployment decision implied.', 'مفاعل الماء المغلي الصغير: أكبر التحولات لهذا الدور في السلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية، والتصنيع في المصنع، ونظام الصيانة. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Design control, the discipline of the licensing basis and engineering judgement stay the foundation of the job.', 'يبقى التحكم في التصميم وانضباط أساس الترخيص والحكم الهندسي أساس العمل.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-dp-dic-l1"}]'::jsonb, array['fr-digital-twin']::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"gevh-smr-centre-2025","label":"GE Vernova · GE Vernova Hitachi SMR engineering and service centre, Ontario (June 2025)","url":"https://www.gevernova.com/news/press-releases/ge-vernova-hitachi-nuclear-energy-canada-small-modular-reactor-engineering-service-centre-ontario","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 26, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:systems-design-plant-engineer:tech-htgr', 'systems-design-plant-engineer', 'tech-htgr', 2, false, '[{"dim":"multi_module","change":"new","text_en":"Several smaller reactor modules may share one plant and one control room. Design and configuration control span several identical units, so a change is assessed once and applied many times.","text_ar":"قد تتشارك عدة وحدات مفاعل أصغر محطة واحدة وغرفة تحكم واحدة. يمتد التصميم والتحكم في التهيئة إلى عدة وحدات متطابقة، فيُقيَّم التغيير مرة ويُطبَّق مرات."},{"dim":"passive_safety","change":"new","text_en":"Gas-cooled designs aim to remove decay heat passively, relying on fuel and materials that tolerate high temperatures. Safety analysis leans on natural circulation and passive heat removal rather than pumped systems.","text_ar":"تسعى التصاميم المبرّدة بالغاز إلى إزالة حرارة الاضمحلال بطريقة خاملة، معتمدة على وقود ومواد تتحمل درجات حرارة عالية. يعتمد تحليل السلامة على الدوران الطبيعي وإزالة الحرارة الخاملة بدلاً من الأنظمة المعتمدة على المضخات."},{"dim":"digital_ic","change":"adapts","text_en":"New digital instrumentation for gas coolant and high-temperature systems. A new digital architecture to understand, modify and keep under configuration control.","text_ar":"أجهزة رقمية جديدة لأنظمة التبريد بالغاز والأنظمة عالية الحرارة. بنية رقمية جديدة يجب فهمها وتعديلها وإبقاؤها تحت التحكم في التهيئة."},{"dim":"factory_fab","change":"new","text_en":"Reactor modules and major components are planned to be factory-built. The design authority works closer to the factory: design changes, deviations and acceptance move upstream.","text_ar":"يُخطَّط لتصنيع وحدات المفاعل والمكونات الرئيسية في المصنع. تعمل جهة التصميم أقرب إلى المصنع، فتنتقل تغييرات التصميم والانحرافات والقبول إلى مراحل أبكر."},{"dim":"maintenance","change":"adapts","text_en":"Gas coolant and a different fuel form change inspection and maintenance tasks. System health monitoring starts from new failure modes and new performance data.","text_ar":"يغيّر التبريد بالغاز وشكل الوقود المختلف مهام الفحص والصيانة. تبدأ مراقبة سلامة الأنظمة من أنماط أعطال جديدة وبيانات أداء جديدة."},{"dim":"systems","change":"new","text_en":"Gas coolant, a different fuel form and high-temperature heat that can also serve industrial processes. Core physics, coolant behaviour and materials differ, so analysis methods and codes change.","text_ar":"تبريد بالغاز وشكل وقود مختلف وحرارة عالية يمكن أن تخدم العمليات الصناعية أيضاً. تختلف فيزياء القلب وسلوك المبرد والمواد، فتتغير طرق التحليل وبرمجياته."}]'::jsonb, 'High-temperature gas-cooled: the biggest shifts for this role are multi-module operation, passive safety, factory fabrication and plant systems, coolant and fuel; digital I&C and the maintenance regime adapt. Planning assumption; no deployment decision implied.', 'المفاعلات عالية الحرارة المبرّدة بالغاز: أكبر التحولات لهذا الدور في التشغيل متعدد الوحدات، والسلامة الخاملة، والتصنيع في المصنع، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من الأجهزة والتحكم الرقمية، ونظام الصيانة. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Design control, the discipline of the licensing basis and engineering judgement stay the foundation of the job.', 'يبقى التحكم في التصميم وانضباط أساس الترخيص والحكم الهندسي أساس العمل.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":2},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":2},{"skill_id":"sk-pf-02-advcool","level":2}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-dp-dic-l1"}]'::jsonb, array['fr-ht-materials','fr-process-heat']::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"osu-e2-center","label":"Oregon State University · NuScale Energy Exploration (E2) Center","url":"https://engineering.oregonstate.edu/facilities/energy-exploration-e2-center","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 27, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:systems-design-plant-engineer:tech-fast', 'systems-design-plant-engineer', 'tech-fast', 3, false, '[{"dim":"multi_module","change":"adapts","text_en":"Fleet concepts with several units change how operations and support are organised. Design and configuration control span several identical units, so a change is assessed once and applied many times.","text_ar":"تغيّر مفاهيم الأساطيل متعددة الوحدات طريقة تنظيم التشغيل والدعم. يمتد التصميم والتحكم في التهيئة إلى عدة وحدات متطابقة، فيُقيَّم التغيير مرة ويُطبَّق مرات."},{"dim":"passive_safety","change":"new","text_en":"Fast-reactor concepts rely on passive heat removal through the coolant''s natural circulation. Safety analysis leans on natural circulation and passive heat removal rather than pumped systems.","text_ar":"تعتمد مفاهيم المفاعلات السريعة على إزالة الحرارة بطريقة خاملة عبر الدوران الطبيعي للمبرد. يعتمد تحليل السلامة على الدوران الطبيعي وإزالة الحرارة الخاملة بدلاً من الأنظمة المعتمدة على المضخات."},{"dim":"digital_ic","change":"adapts","text_en":"Instrumentation designed for liquid-metal coolant and a fast neutron spectrum. A new digital architecture to understand, modify and keep under configuration control.","text_ar":"أجهزة مصممة لمبرد معدني سائل وطيف نيوتروني سريع. بنية رقمية جديدة يجب فهمها وتعديلها وإبقاؤها تحت التحكم في التهيئة."},{"dim":"factory_fab","change":"adapts","text_en":"More factory-built components and modular construction. The design authority works closer to the factory: design changes, deviations and acceptance move upstream.","text_ar":"مكونات مصنّعة في المصنع وإنشاء معياري أكثر. تعمل جهة التصميم أقرب إلى المصنع، فتنتقل تغييرات التصميم والانحرافات والقبول إلى مراحل أبكر."},{"dim":"maintenance","change":"adapts","text_en":"Liquid-metal coolant changes how components are inspected, drained and handled. System health monitoring starts from new failure modes and new performance data.","text_ar":"يغيّر المبرد المعدني السائل طريقة فحص المكونات وتصريفها ومناولتها. تبدأ مراقبة سلامة الأنظمة من أنماط أعطال جديدة وبيانات أداء جديدة."},{"dim":"systems","change":"new","text_en":"Liquid-metal coolant handling and chemistry, and fast-spectrum reactor physics. Core physics, coolant behaviour and materials differ, so analysis methods and codes change.","text_ar":"مناولة المبرد المعدني السائل وكيمياؤه، وفيزياء المفاعلات ذات الطيف السريع. تختلف فيزياء القلب وسلوك المبرد والمواد، فتتغير طرق التحليل وبرمجياته."}]'::jsonb, 'Fast reactors with liquid-metal coolant: the biggest shifts for this role are passive safety and plant systems, coolant and fuel; multi-module operation, digital I&C, factory fabrication and the maintenance regime adapt. Planning assumption; no deployment decision implied.', 'المفاعلات السريعة المبرّدة بالمعادن السائلة: أكبر التحولات لهذا الدور في السلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية، والتصنيع في المصنع، ونظام الصيانة. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Design control, the discipline of the licensing basis and engineering judgement stay the foundation of the job.', 'يبقى التحكم في التصميم وانضباط أساس الترخيص والحكم الهندسي أساس العمل.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":1},{"skill_id":"sk-pf-02-advcool","level":2}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-dp-dic-l1"}]'::jsonb, array['fr-liquid-metal']::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 28, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:systems-design-plant-engineer:tech-msr', 'systems-design-plant-engineer', 'tech-msr', 4, false, '[{"dim":"multi_module","change":"adapts","text_en":"Modular plant concepts with several units. Design and configuration control span several identical units, so a change is assessed once and applied many times.","text_ar":"مفاهيم محطات معيارية بعدة وحدات. يمتد التصميم والتحكم في التهيئة إلى عدة وحدات متطابقة، فيُقيَّم التغيير مرة ويُطبَّق مرات."},{"dim":"passive_safety","change":"new","text_en":"Molten salt concepts rely on passive features of the salt and the design to remove heat. Safety analysis leans on natural circulation and passive heat removal rather than pumped systems.","text_ar":"تعتمد مفاهيم الأملاح المنصهرة على الخصائص الخاملة للملح والتصميم لإزالة الحرارة. يعتمد تحليل السلامة على الدوران الطبيعي وإزالة الحرارة الخاملة بدلاً من الأنظمة المعتمدة على المضخات."},{"dim":"digital_ic","change":"adapts","text_en":"Instrumentation and sampling designed for hot salt systems. A new digital architecture to understand, modify and keep under configuration control.","text_ar":"أجهزة وأخذ عينات مصممة لأنظمة الأملاح الساخنة. بنية رقمية جديدة يجب فهمها وتعديلها وإبقاؤها تحت التحكم في التهيئة."},{"dim":"factory_fab","change":"adapts","text_en":"Factory-built modules for salt systems. The design authority works closer to the factory: design changes, deviations and acceptance move upstream.","text_ar":"وحدات مصنّعة في المصنع لأنظمة الأملاح. تعمل جهة التصميم أقرب إلى المصنع، فتنتقل تغييرات التصميم والانحرافات والقبول إلى مراحل أبكر."},{"dim":"maintenance","change":"adapts","text_en":"Salt-wetted components bring new handling and inspection tasks. System health monitoring starts from new failure modes and new performance data.","text_ar":"تجلب المكونات الملامسة للملح مهام مناولة وفحص جديدة. تبدأ مراقبة سلامة الأنظمة من أنماط أعطال جديدة وبيانات أداء جديدة."},{"dim":"systems","change":"new","text_en":"Salt chemistry and materials replace water chemistry. Core physics, coolant behaviour and materials differ, so analysis methods and codes change.","text_ar":"تحل كيمياء الأملاح وموادها محل كيمياء الماء. تختلف فيزياء القلب وسلوك المبرد والمواد، فتتغير طرق التحليل وبرمجياته."}]'::jsonb, 'Molten salt: the biggest shifts for this role are passive safety and plant systems, coolant and fuel; multi-module operation, digital I&C, factory fabrication and the maintenance regime adapt. Planning assumption; no deployment decision implied.', 'مفاعلات الأملاح المنصهرة: أكبر التحولات لهذا الدور في السلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية، والتصنيع في المصنع، ونظام الصيانة. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Design control, the discipline of the licensing basis and engineering judgement stay the foundation of the job.', 'يبقى التحكم في التصميم وانضباط أساس الترخيص والحكم الهندسي أساس العمل.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":1},{"skill_id":"sk-pf-02-advcool","level":2}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-dp-dic-l1"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 29, 'p-training-mgr', '2026-10-11T08:00:00Z')
